-- CLUSTER-D-PROBES-1 (2026-10-20, pillar autonomy; agent_issues 100248 CHAOS-DRILL-FAILED-1 control:control-alternate-probes, 2826 PATHS-UNTESTED-1, 2067 CODE-TASK-PREFLIGHT-1; owner directive 2026-10-20: every open issue
-- is cleared server-side within 24 hours, no doer is left without a probe). Two read-only closing probes, no worker change, no alternate_tested_at written (only a passing drill stamps).
-- 1. model-health-sweep (control_registry, registered 2026-10-19 with MODEL-HEALTH-SWEEP-1, qnfo-lifecycle 1.13.0) has an alternate_path and neither a probe nor a tested date, so
--    v_control_alternate_untested.controls_untested_without_probe reads 1 and the control-alternate-probes probe, which requires 0, failed the 00:00Z drill (CHAOS-DRILL-FAILED-1 issue 100248, probe-failing).
--    Measured 2026-10-20 05:5xZ (SELECT only): controls_untested_without_probe 1, the alternate (the daily backlog member's model-health predicate) ran at 02:00:47Z today and every day since 2026-10-17, the detector
--    fm-model-health-issue-stale is active and passes. The probe reads those three things; once it exists the count is 0, the next drill passes control-alternate-probes (closing issue 100248 itself), stamps model-health-sweep,
--    and the 2826 list of untested controls is empty once the q08-ground-precheck probe (never run, passes read-only today: switch on, detector active, q08-signal-engine 0.32.0-codeagent deployed) is drilled too.
-- 2. issue-2067 closing probe. The 14-day window matched the substring larger than anywhere in last_error or merge_note, so it counted (a) 15 publish_failed rows whose error is publish: patch larger than N chars (a publish-size
--    failure after the propose step, issue 100184's cap), (b) CODE-TASK-REROUTE-1 rows (file larger than 60000 chars needs an anchor), which are the preflight refusing at intake before any model call, the behaviour the issue asks for,
--    and (c) closed tasks of 2026-10-06 and 2026-10-07 inside the 14-day window. The defect is a task that reached the propose step and died for an anchor that occurs 0 times or a file over the loop's cap. The restated probe counts
--    exactly those (a last_error that starts with the raw message, so the REROUTE-1 prefix and the publish: prefix do not match) over tasks created since the preflight went live (2026-10-12T18:00Z, qnfo-code-orchestrator 0.14.0) and
--    inside 14 days, and keeps the issue's second condition as a measured rate: merged over merged, failed, publish_failed and needs_human of those tasks at or above 0.45. Measured at 05:5xZ: see the evidence in the decision_log row.
-- 3. issue-2007 closing probe (TP-1c-ANCHOR-REPAIR). The probe counted every code-task.fail event whose text contains the word anchor, including the tasks NEEDS-ANCHOR-ROUTE-1 and CODE-TASK-REROUTE-1 end on
--    purpose (a file over 60000 chars with no keyword hit: failed, the issue keeps a session-task line), so it could not pass before 2026-11-02 whatever the repair did. The issue's own definition of done is
--    code_tasks rows whose last_error mentions an anchor ending needs_human = 0 over 14 days while the task count is not lower. Measured 2026-10-20 06:0xZ: needs_human with an anchor error in 14 days 0
--    (7 closed on 2026-10-06 and 2026-10-07, 4 failed and rerouted), tasks 327 in the last 14 days against 56 in the 14 before, 134 code-task.anchor-located events (the model-assisted locator and the keyword
--    fallback of ANCHOR-LOCATOR-1, ANCHOR-KEYWORD-FALLBACK-1 and ANCHOR-MULTILINE-1 are in qnfo-code-orchestrator on main). The restated probe reads exactly that.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM control_alternate_probes WHERE control = 'model-health-sweep' AND window_note LIKE '1560 minutes for the daily backlog member%'; UPDATE control_registry SET evidence = replace(evidence, ' | PATHS-UNTESTED-1 (CLUSTER-D-PROBES-1 2026-10-20): probed by its control_alternate_probes row (the daily member ran inside 1560 minutes, the stale-issue detector is active and ran inside 120 minutes, the switch reads on or off), which the chaos drill runs every 360 minutes, and only a passing probe stamps alternate_tested_at', '') WHERE control = 'model-health-sweep'; UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND status IN (''merged'',''closed'',''failed'',''needs_human'')) < 8 THEN ''pending: '' || (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND status IN (''merged'',''closed'',''failed'',''needs_human'')) || '' of 8 finished tasks in the last 14 days'' WHEN (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND (COALESCE(last_error,'''') || COALESCE(merge_note,'''')) LIKE ''%larger than%'') + (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND (COALESCE(last_error,'''') || COALESCE(merge_note,'''')) LIKE ''%anchor occurs 0%'') = 0 THEN ''ok'' ELSE ''dead-on-arrival tasks were created in the last 14 days: '' || (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND ((COALESCE(last_error,'''') || COALESCE(merge_note,'''')) LIKE ''%larger than%'' OR (COALESCE(last_error,'''') || COALESCE(merge_note,'''')) LIKE ''%anchor occurs 0%'')) END AS observed' WHERE class = 'issue-2067' AND instr(verify_probe, 'since the intake preflight went live') > 0; UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''code-task.anchor-located'' AND status = ''ok'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-14 days'')) = 0 THEN ''defect: no anchor-located event in 14 days'' WHEN (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''code-task.fail'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-14 days'') AND instr(lower(text), ''anchor'') > 0) > 0 THEN ''defect: '' || (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''code-task.fail'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-14 days'') AND instr(lower(text), ''anchor'') > 0) || '' task read-steps failed on an anchor in the last 14 days'' ELSE ''ok'' END AS observed /* ANCHOR-PROBE-REACHABLE-1 */' WHERE class = 'issue-2007' AND instr(verify_probe, 'ended needs_human on an anchor') > 0
-- Rollback note: the decision_log row stays (append-only), and an alternate_tested_at the drill stamped on the passing probe stays (it was earned).

INSERT OR IGNORE INTO control_alternate_probes (control, probe_sql, window_note, enabled) VALUES
 ('model-health-sweep',
  'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM remediation_contracts WHERE class = ''fm-model-health-issue-stale'' AND status = ''active'') THEN ''the detector fm-model-health-issue-stale is missing or not active'' WHEN COALESCE((SELECT lower(trim(value)) FROM ops_config WHERE key = ''model_health_sweep''), ''on'') NOT IN (''on'', ''off'') THEN ''the switch model_health_sweep reads '' || COALESCE((SELECT value FROM ops_config WHERE key = ''model_health_sweep''), ''NULL'') || '', not on or off'' WHEN COALESCE((SELECT MAX(ts) FROM cloud_ops_events WHERE job = ''qnfo-backlog-exec'' AND kind = ''job-run''), '''') < strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-1560 minutes'') THEN ''the daily backlog member did not run in 1560 minutes, so the alternate of the sweep (its model-health predicate on the 02:00 UTC tick) is not running'' WHEN COALESCE((SELECT last_attempt_at FROM remediation_contracts WHERE class = ''fm-model-health-issue-stale''), '''') < datetime(''now'', ''-120 minutes'') THEN ''the detector fm-model-health-issue-stale did not run in 120 minutes'' ELSE ''ok'' END AS observed',
  '1560 minutes for the daily backlog member (qnfo-lifecycle backlogMod, the 02:00 UTC tick, one job-run event a day, plus the 120 minutes SLA-120M-1 allows) and 120 minutes for the detector fm-model-health-issue-stale, which reads the same predicate and counts a recovered model whose issue stays open: the sweep is the hourly path and the daily member is the path it falls back to when ops_config model_health_sweep is off, so the probe reads that the fallback ran today and the detector that would notice a stuck issue is alive; the member closed model-health issues on 2026-10-11, 2026-10-02 and 2026-09-29', 1);

UPDATE control_registry SET evidence = evidence || ' | PATHS-UNTESTED-1 (CLUSTER-D-PROBES-1 2026-10-20): probed by its control_alternate_probes row (the daily member ran inside 1560 minutes, the stale-issue detector is active and ran inside 120 minutes, the switch reads on or off), which the chaos drill runs every 360 minutes, and only a passing probe stamps alternate_tested_at'
WHERE control = 'model-health-sweep' AND evidence NOT LIKE '%CLUSTER-D-PROBES-1 2026-10-20%';

UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM code_tasks WHERE created_at >= ''2026-10-12T18:00'' AND created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND status IN (''merged'',''closed'',''failed'',''needs_human'',''publish_failed'')) < 8 THEN ''pending: '' || (SELECT COUNT(*) FROM code_tasks WHERE created_at >= ''2026-10-12T18:00'' AND created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND status IN (''merged'',''closed'',''failed'',''needs_human'',''publish_failed'')) || '' of 8 finished tasks since the intake preflight went live (2026-10-12T18:00) and inside 14 days'' WHEN (SELECT COUNT(*) FROM code_tasks WHERE created_at >= ''2026-10-12T18:00'' AND created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND (instr(COALESCE(last_error,''''),''anchor occurs 0'') = 1 OR instr(COALESCE(last_error,''''),''file larger than'') = 1)) > 0 THEN ''dead-on-arrival tasks reached the propose step in the last 14 days: '' || (SELECT COUNT(*) FROM code_tasks WHERE created_at >= ''2026-10-12T18:00'' AND created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND (instr(COALESCE(last_error,''''),''anchor occurs 0'') = 1 OR instr(COALESCE(last_error,''''),''file larger than'') = 1)) WHEN (SELECT COUNT(*) FROM code_tasks WHERE created_at >= ''2026-10-12T18:00'' AND created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND status = ''merged'') * 100 < 45 * (SELECT COUNT(*) FROM code_tasks WHERE created_at >= ''2026-10-12T18:00'' AND created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND status IN (''merged'',''failed'',''needs_human'',''publish_failed'')) THEN ''engine success rate (merged over merged, failed, publish_failed and needs_human) is under 0.45: '' || (SELECT COUNT(*) FROM code_tasks WHERE created_at >= ''2026-10-12T18:00'' AND created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND status = ''merged'') || '' of '' || (SELECT COUNT(*) FROM code_tasks WHERE created_at >= ''2026-10-12T18:00'' AND created_at >= strftime(''%Y-%m-%dT%H:%M'',''now'',''-14 days'') AND status IN (''merged'',''failed'',''needs_human'',''publish_failed'')) ELSE ''ok'' END AS observed'
WHERE class = 'issue-2067' AND instr(verify_probe, 'since the intake preflight went live') = 0;

UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''code-task.anchor-located'' AND status = ''ok'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-14 days'')) = 0 THEN ''defect: no anchor-located event in 14 days, so the anchor repair is not running'' WHEN (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-14 days'') AND status = ''needs_human'' AND instr(lower(COALESCE(last_error,'''')),''anchor'') > 0) > 0 THEN ''defect: '' || (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-14 days'') AND status = ''needs_human'' AND instr(lower(COALESCE(last_error,'''')),''anchor'') > 0) || '' tasks ended needs_human on an anchor in the last 14 days'' WHEN (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-14 days'')) < (SELECT COUNT(*) FROM code_tasks WHERE created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-28 days'') AND created_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-14 days'')) THEN ''defect: the task count of the last 14 days is lower than the 14 days before it'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-2007' AND instr(verify_probe, 'ended needs_human on an anchor') = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'agent-clusterD-a0676665',
  'a control alternate counts as tested only while a probe on its own evidence passes, and a closing probe measures the defect the issue names and not the preflight that now prevents it',
  'CLUSTER-D-PROBES-1: a control_alternate_probes row for model-health-sweep (the one control that kept control-alternate-probes failing its drill, controls_untested_without_probe 1, issue 100248) and the closing probe of issue 2067 restated over the window after the intake preflight, so a refusal made before any model call and a publish-size failure that belongs to issue 100184 no longer read as dead-on-arrival tasks',
  'qnfo-audit 2026-10-20 05:5xZ (SELECT only): v_control_alternate_untested controls_untested_without_probe 1 (model-health-sweep), control_alternate_probes control-alternate-probes last_pass 0 at 00:00:35Z, backlog member job-run at 02:00:47Z, fm-model-health-issue-stale active and passing, q08-ground-precheck probe conditions read ok, code_tasks since 2026-10-12T18:00Z with a raw anchor-occurs-0 or file-larger-than error 0',
  'migration merged',
  'one control_alternate_probes row, one control_registry evidence suffix, one remediation_contracts probe, no worker change',
  'the Rollback header of migrations/2026-10-20-cluster-d-probes.sql',
  'a control with a declared alternate and no probe is drilled by the 6-hourly chaos drill, an issue closing probe reads the defect and not its fix',
  'control-alternate-probes passes at the next drill (issue 100248 closes itself), issue-2067 probe reads ok',
  'none',
  'd1:qnfo-audit read-only probe runs, node:sqlite fixtures in migrations/cluster-d-probes.test.mjs'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'CLUSTER-D-PROBES-1:%');
